package com.example.g2glasses.gateway.protocol

import com.example.g2glasses.glassesui.GlassesPage
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * Golden bytes generated by running the Python port (gpsnmeajp/men-g2-ble-gateway,
 * mentraos/g2) with the same inputs, so the Kotlin port sends exactly what works on the glasses.
 */
class G2ProtocolTest {

    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }
    private fun ByteArray.hex() = joinToString("") { "%02x".format(it) }

    @Test
    fun crc16_matchesG2kt() {
        assertEquals(0xd26e, Crc16.of("hello".toByteArray()))
        assertEquals(0xffff, Crc16.of(ByteArray(0)))
        assertEquals(0x3fbd, Crc16.of(ByteArray(256) { it.toByte() }))
    }

    private fun payload(n: Int) = ByteArray(n) { (it % 251).toByte() }

    @Test
    fun singleFramePacket() {
        val p = Packets.build(7, ServiceId.EVEN_HUB, payload(5), reserveFlag = true)
        assertEquals("aa2107070101e0200001020304" + "0f1c", p.single().hex())
    }

    @Test
    fun exactlyFullPayload_getsCrcOnlyFrame() {
        val p = Packets.build(7, ServiceId.EVEN_HUB, payload(236), reserveFlag = true)
        assertEquals(2, p.size)
        assertEquals(244, p[0].size)
        assertEquals("aa2107ec0201e020", p[0].copyOfRange(0, 8).hex())
        assertEquals("aa2107020202e0206a71", p[1].hex())
    }

    @Test
    fun multiFramePayload() {
        val p = Packets.build(7, ServiceId.EVEN_HUB, payload(500), reserveFlag = true)
        assertEquals(listOf(244, 244, 38), p.map { it.size })
        assertEquals(listOf("aa2107ec0301e020", "aa2107ec0302e020", "aa21071e0303e020"), p.map { it.copyOfRange(0, 8).hex() })
        assertEquals("f7f88d11", p[2].copyOfRange(34, 38).hex())
    }

    @Test
    fun frameAssembler_rejoinsMultiFrameMessages() {
        val body = payload(500)
        val asm = FrameAssembler()
        val frames = Packets.build(3, ServiceId.EVEN_HUB, body, reserveFlag = false)
        assertNull(asm.accept(frames[0], "R"))
        assertNull(asm.accept(frames[1], "R"))
        val (service, joined) = asm.accept(frames[2], "R")!!
        assertEquals(ServiceId.EVEN_HUB, service)
        assertArrayEquals(body, joined)
    }

    @Test
    fun setupMessages_matchPythonPort() {
        assertEquals("080410031a0408011004", G2Messages.auth(3).hex())
        assertEquals("0805100422020801", G2Messages.pipeRoleChange(4).hex())
        assertEquals("088001100582080808a09cedc7061000", G2Messages.timeSync(5, 1761300000).hex())
        assertEquals("080e10066a00", G2Messages.baseHeartbeat(6).hex())
        assertEquals("0801100b1a020804", G2Messages.skipOnboarding(11).hex())
        assertEquals("080a100c6a0408001050", G2Messages.heyEvenOff(12).hex())
        assertEquals("0801100d1a0c4a0a08001000180120002801", G2Messages.universeSettings(13).hex())
        assertEquals("0802100e22020801", G2Messages.requestDeviceInfo(14).hex())
        assertEquals("0801100f1a080801100118052801", G2Messages.calendarDefaults(15).hex())
        assertEquals("0802101022171215080410031a0301020320042a040103020230013801", G2Messages.dashboardDefaults(16).hex())
    }

    @Test
    fun displayMessages_matchPythonPort() {
        val boxes = GlassesPage.fullScreenText("hello").boxes
        val container = "1a2c08011a280800100018c00420a002280030003800400448015209746578742d6d61696e5801620568656c6c6f"
        assertEquals("08001008$container", G2Messages.createPage(8, boxes).hex())
        assertEquals("08071009" + "3a" + container.drop(2), G2Messages.rebuildPage(9, boxes).hex())
        assertEquals("080510004a0d0801180020052a0568656c6c6f", G2Messages.updateText(1, "hello").hex())
        assertEquals("080c100a7200", G2Messages.evenHubHeartbeat(10).hex())
        assertEquals("080910005a020800", G2Messages.shutdownPage().hex())
    }

    @Test
    fun launchMenu_matchesPythonPort() {
        assertEquals(10066, G2Messages.appIdFor("com.example.g2glasses.launch"))
        assertEquals(10421, G2Messages.appIdFor("men-g2-ble-gateway.launch"))
        assertEquals(
            "080010111a4d08051204080020041213080110011a0a202043617074696f6e7320d24e120e080110011a0520202d2d2d20a852" +
                "120e080110011a0520202d2d2d20a952120e080110011a0520202d2d2d20aa52",
            G2Messages.launchMenu(17, "com.example.g2glasses.launch", "Captions").hex(),
        )
    }

    @Test
    fun responses_decodeTouchAuthAndDeviceInfo() {
        assertEquals(listOf(G2Response.Touch(OsEvent.DOUBLE_CLICK)), G2Responses.parse(ServiceId.EVEN_HUB, hex("08026a061a0408031001")))
        assertEquals(listOf(G2Response.Authenticated(true)), G2Responses.parse(ServiceId.DEVICE_SETTINGS, hex("08041a020801")))
        assertEquals(
            listOf(G2Response.DeviceInfo(87, true, "2.2.20", "2.2.21")),
            G2Responses.parse(ServiceId.G2_SETTING, hex("080222142a06322e322e32303206322e322e323160576801")),
        )
    }
}
